// src/core/memory.zig
const std = @import("std");
const mem = std.mem;
const Allocator = mem.Allocator;

pub const ArenaAllocator = struct {
    inner: std.heap.ArenaAllocator,

    pub fn init(backing: Allocator) ArenaAllocator {
        return .{ .inner = std.heap.ArenaAllocator.init(backing) };
    }

    pub fn deinit(self: *ArenaAllocator) void {
        self.inner.deinit();
    }

    pub fn allocator(self: *ArenaAllocator) Allocator {
        return self.inner.allocator();
    }
};

pub const PoolAllocator = struct {
    const FreeNode = struct { next: ?*FreeNode };

    slab: []u8,
    block_size: usize,
    free_list: ?*FreeNode,
    backing: Allocator,
    vtable: Allocator.VTable,

    pub fn init(backing: Allocator, block_size: usize, block_count: usize) !PoolAllocator {
        if (block_size < @sizeOf(FreeNode)) return error.InvalidBlockSize;
        if (block_count == 0) return error.InvalidBlockCount;
        const aligned_block = mem.alignForward(usize, block_size, @alignOf(FreeNode));
        const total = aligned_block * block_count;
        const slab = try backing.alignedAlloc(u8, @alignOf(FreeNode), total);
        errdefer backing.free(slab);

        var free_list: ?*FreeNode = null;
        var i: usize = block_count;
        while (i > 0) {
            i -= 1;
            const ptr: *FreeNode = @ptrCast(@alignCast(slab.ptr + i * aligned_block));
            ptr.next = free_list;
            free_list = ptr;
        }

        var pool = PoolAllocator{
            .slab = slab,
            .block_size = aligned_block,
            .free_list = free_list,
            .backing = backing,
            .vtable = .{
                .alloc = poolAlloc,
                .resize = poolResize,
                .free = poolFree,
            },
        };
        _ = pool;
        return PoolAllocator{
            .slab = slab,
            .block_size = aligned_block,
            .free_list = free_list,
            .backing = backing,
            .vtable = .{
                .alloc = poolAlloc,
                .resize = poolResize,
                .free = poolFree,
            },
        };
    }

    pub fn deinit(self: *PoolAllocator) void {
        self.backing.free(self.slab);
    }

    pub fn allocator(self: *PoolAllocator) Allocator {
        return Allocator{ .ptr = self, .vtable = &self.vtable };
    }

    fn poolAlloc(ctx: *anyopaque, n: usize, log2_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self: *PoolAllocator = @ptrCast(@alignCast(ctx));
        const alignment = @as(usize, 1) << @intCast(log2_align);
        if (n > self.block_size) return null;
        if (alignment > @alignOf(FreeNode)) return null;
        const node = self.free_list orelse return null;
        self.free_list = node.next;
        const ptr: [*]u8 = @ptrCast(node);
        @memset(ptr[0..n], 0);
        return ptr;
    }

    fn poolResize(ctx: *anyopaque, buf: []u8, log2_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = ctx;
        _ = log2_align;
        _ = ret_addr;
        return new_len <= buf.len;
    }

    fn poolFree(ctx: *anyopaque, buf: []u8, log2_align: u8, ret_addr: usize) void {
        _ = log2_align;
        _ = ret_addr;
        const self: *PoolAllocator = @ptrCast(@alignCast(ctx));
        const node: *FreeNode = @ptrCast(@alignCast(buf.ptr));
        node.next = self.free_list;
        self.free_list = node;
    }
};

pub const SlabAllocator = struct {
    const ObjectHeader = struct { in_use: bool };

    slab: []u8,
    object_size: usize,
    object_count: usize,
    backing: Allocator,
    vtable: Allocator.VTable,
    mutex: std.Thread.Mutex,

    pub fn init(backing: Allocator, object_size: usize, object_count: usize) !SlabAllocator {
        if (object_size == 0 or object_count == 0) return error.InvalidParameters;
        const header_size = mem.alignForward(usize, @sizeOf(ObjectHeader), @alignOf(f64));
        const aligned_obj = mem.alignForward(usize, object_size, @alignOf(f64));
        const slot_size = header_size + aligned_obj;
        const total = slot_size * object_count;
        const slab = try backing.alignedAlloc(u8, @alignOf(f64), total);
        errdefer backing.free(slab);

        var i: usize = 0;
        while (i < object_count) : (i += 1) {
            const header: *ObjectHeader = @ptrCast(@alignCast(slab.ptr + i * slot_size));
            header.in_use = false;
        }

        return SlabAllocator{
            .slab = slab,
            .object_size = aligned_obj,
            .object_count = object_count,
            .backing = backing,
            .vtable = .{
                .alloc = slabAlloc,
                .resize = slabResize,
                .free = slabFree,
            },
            .mutex = .{},
        };
    }

    pub fn deinit(self: *SlabAllocator) void {
        self.backing.free(self.slab);
    }

    pub fn allocator(self: *SlabAllocator) Allocator {
        return Allocator{ .ptr = self, .vtable = &self.vtable };
    }

    fn slotSize(self: *const SlabAllocator) usize {
        const header_size = mem.alignForward(usize, @sizeOf(ObjectHeader), @alignOf(f64));
        return header_size + self.object_size;
    }

    fn slabAlloc(ctx: *anyopaque, n: usize, log2_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self: *SlabAllocator = @ptrCast(@alignCast(ctx));
        const alignment = @as(usize, 1) << @intCast(log2_align);
        if (n > self.object_size) return null;
        if (alignment > @alignOf(f64)) return null;
        self.mutex.lock();
        defer self.mutex.unlock();
        const header_size = mem.alignForward(usize, @sizeOf(ObjectHeader), @alignOf(f64));
        const slot = self.slotSize();
        var i: usize = 0;
        while (i < self.object_count) : (i += 1) {
            const hdr: *ObjectHeader = @ptrCast(@alignCast(self.slab.ptr + i * slot));
            if (!hdr.in_use) {
                hdr.in_use = true;
                const data_ptr = self.slab.ptr + i * slot + header_size;
                @memset(data_ptr[0..n], 0);
                return data_ptr;
            }
        }
        return null;
    }

    fn slabResize(ctx: *anyopaque, buf: []u8, log2_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = ctx;
        _ = log2_align;
        _ = ret_addr;
        return new_len <= buf.len;
    }

    fn slabFree(ctx: *anyopaque, buf: []u8, log2_align: u8, ret_addr: usize) void {
        _ = log2_align;
        _ = ret_addr;
        const self: *SlabAllocator = @ptrCast(@alignCast(ctx));
        const header_size = mem.alignForward(usize, @sizeOf(ObjectHeader), @alignOf(f64));
        const slot = self.slotSize();
        const base = self.slab.ptr;
        const end = base + self.slab.len;
        const buf_ptr = buf.ptr;
        if (@intFromPtr(buf_ptr) < @intFromPtr(base) or @intFromPtr(buf_ptr) >= @intFromPtr(end)) return;
        const offset = @intFromPtr(buf_ptr) - @intFromPtr(base);
        const slot_idx = (offset - header_size) / slot;
        if (slot_idx >= self.object_count) return;
        self.mutex.lock();
        defer self.mutex.unlock();
        const hdr: *ObjectHeader = @ptrCast(@alignCast(base + slot_idx * slot));
        hdr.in_use = false;
    }
};

pub const BuddyAllocator = struct {
    const MIN_ORDER: usize = 4;
    const MAX_ORDER: usize = 30;

    const BlockHeader = packed struct {
        order: u8,
        free: bool,
        _pad: u7 = 0,
    };

    region: []u8,
    order: usize,
    free_lists: [MAX_ORDER + 1]?usize,
    backing: Allocator,
    vtable: Allocator.VTable,
    mutex: std.Thread.Mutex,

    pub fn init(backing: Allocator, size_log2: usize) !BuddyAllocator {
        if (size_log2 < MIN_ORDER or size_log2 > MAX_ORDER) return error.InvalidOrder;
        const size = @as(usize, 1) << @intCast(size_log2);
        const region = try backing.alignedAlloc(u8, mem.page_size, size);
        errdefer backing.free(region);
        @memset(region, 0);

        var free_lists = [_]?usize{null} ** (MAX_ORDER + 1);
        const hdr: *BlockHeader = @ptrCast(@alignCast(region.ptr));
        hdr.order = @intCast(size_log2);
        hdr.free = true;
        free_lists[size_log2] = 0;

        return BuddyAllocator{
            .region = region,
            .order = size_log2,
            .free_lists = free_lists,
            .backing = backing,
            .vtable = .{
                .alloc = buddyAlloc,
                .resize = buddyResize,
                .free = buddyFree,
            },
            .mutex = .{},
        };
    }

    pub fn deinit(self: *BuddyAllocator) void {
        self.backing.free(self.region);
    }

    pub fn allocator(self: *BuddyAllocator) Allocator {
        return Allocator{ .ptr = self, .vtable = &self.vtable };
    }

    fn orderForSize(n: usize) usize {
        var o = MIN_ORDER;
        while ((@as(usize, 1) << @intCast(o)) < n + @sizeOf(BlockHeader)) : (o += 1) {}
        return o;
    }

    fn buddyOffset(offset: usize, ord: usize) usize {
        return offset ^ (@as(usize, 1) << @intCast(ord));
    }

    fn buddyAlloc(ctx: *anyopaque, n: usize, log2_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self: *BuddyAllocator = @ptrCast(@alignCast(ctx));
        const alignment = @as(usize, 1) << @intCast(log2_align);
        if (alignment > mem.page_size) return null;
        self.mutex.lock();
        defer self.mutex.unlock();
        const needed_order = orderForSize(n);
        if (needed_order > self.order) return null;

        var found_order: ?usize = null;
        var search_order = needed_order;
        while (search_order <= self.order) : (search_order += 1) {
            if (self.free_lists[search_order] != null) {
                found_order = search_order;
                break;
            }
        }
        const fo = found_order orelse return null;

        const offset = self.free_lists[fo].?;
        self.free_lists[fo] = null;

        var current_order = fo;
        while (current_order > needed_order) : (current_order -= 1) {
            const half = @as(usize, 1) << @intCast(current_order - 1);
            const buddy_off = offset + half;
            const buddy_hdr: *BlockHeader = @ptrCast(@alignCast(self.region.ptr + buddy_off));
            buddy_hdr.order = @intCast(current_order - 1);
            buddy_hdr.free = true;
            self.free_lists[current_order - 1] = buddy_off;
        }

        const hdr: *BlockHeader = @ptrCast(@alignCast(self.region.ptr + offset));
        hdr.order = @intCast(needed_order);
        hdr.free = false;
        const data = self.region.ptr + offset + @sizeOf(BlockHeader);
        @memset(data[0..n], 0);
        return data;
    }

    fn buddyResize(ctx: *anyopaque, buf: []u8, log2_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = ctx;
        _ = log2_align;
        _ = ret_addr;
        const hdr_size = @sizeOf(BlockHeader);
        const hdr: *BlockHeader = @ptrCast(@alignCast(buf.ptr - hdr_size));
        const block_size = (@as(usize, 1) << @intCast(hdr.order)) - hdr_size;
        return new_len <= block_size;
    }

    fn buddyFree(ctx: *anyopaque, buf: []u8, log2_align: u8, ret_addr: usize) void {
        _ = log2_align;
        _ = ret_addr;
        const self: *BuddyAllocator = @ptrCast(@alignCast(ctx));
        self.mutex.lock();
        defer self.mutex.unlock();
        const hdr_size = @sizeOf(BlockHeader);
        const data_offset = @intFromPtr(buf.ptr) - @intFromPtr(self.region.ptr);
        const block_offset = data_offset - hdr_size;
        const hdr: *BlockHeader = @ptrCast(@alignCast(self.region.ptr + block_offset));
        hdr.free = true;

        var current_offset = block_offset;
        var current_order = @as(usize, hdr.order);

        while (current_order < self.order) {
            const buddy_off = buddyOffset(current_offset, current_order);
            if (buddy_off + (@as(usize, 1) << @intCast(current_order)) > self.region.len) break;
            const buddy_hdr: *BlockHeader = @ptrCast(@alignCast(self.region.ptr + buddy_off));
            if (!buddy_hdr.free or buddy_hdr.order != current_order) break;
            buddy_hdr.free = false;
            self.free_lists[current_order] = null;
            current_offset = @min(current_offset, buddy_off);
            current_order += 1;
            const merged_hdr: *BlockHeader = @ptrCast(@alignCast(self.region.ptr + current_offset));
            merged_hdr.order = @intCast(current_order);
            merged_hdr.free = true;
        }

        self.free_lists[current_order] = current_offset;
    }
};
