```zig
// src/hw/accel/accel_interface.zig
const std = @import("std");
const builtin = @import("builtin");
const build_options = @import("build_options");
const Tensor = @import("../../core/tensor.zig").Tensor;
const Allocator = std.mem.Allocator;

pub const gpu_enabled: bool = if (@hasDecl(build_options, "gpu")) build_options.gpu else false;

pub const RSFAccelerator = struct {
    dim: usize,
    s_weights: ?[]f16,
    t_weights: ?[]f16,
    s_rows: usize,
    s_cols: usize,
    t_rows: usize,
    t_cols: usize,
    allocator: Allocator,

    pub fn init(dim: usize, alloc: Allocator) !RSFAccelerator {
        if (!gpu_enabled) return error.GPUUnsupportedConfiguration;
        return RSFAccelerator{
            .dim = dim,
            .s_weights = null,
            .t_weights = null,
            .s_rows = 0,
            .s_cols = 0,
            .t_rows = 0,
            .t_cols = 0,
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *RSFAccelerator) void {
        if (!gpu_enabled) return;
        if (self.s_weights) |sw| self.allocator.free(sw);
        if (self.t_weights) |tw| self.allocator.free(tw);
        self.s_weights = null;
        self.t_weights = null;
    }

    pub fn setWeightsS(self: *RSFAccelerator, data: []const f16, rows: usize, cols: usize) !void {
        if (!gpu_enabled) return error.GPUUnsupportedConfiguration;
        if (data.len != rows * cols) return error.ShapeMismatch;
        if (self.s_weights) |sw| self.allocator.free(sw);
        const buf = try self.allocator.alloc(f16, data.len);
        @memcpy(buf, data);
        self.s_weights = buf;
        self.s_rows = rows;
        self.s_cols = cols;
    }

    pub fn setWeightsT(self: *RSFAccelerator, data: []const f16, rows: usize, cols: usize) !void {
        if (!gpu_enabled) return error.GPUUnsupportedConfiguration;
        if (data.len != rows * cols) return error.ShapeMismatch;
        if (self.t_weights) |tw| self.allocator.free(tw);
        const buf = try self.allocator.alloc(f16, data.len);
        @memcpy(buf, data);
        self.t_weights = buf;
        self.t_rows = rows;
        self.t_cols = cols;
    }

    pub fn forwardFromTensor(self: *RSFAccelerator, x: *Tensor, alloc: Allocator) !Tensor {
        if (!gpu_enabled) return error.GPUUnsupportedConfiguration;
        if (x.shape.dims.len != 2) return error.InvalidShape;
        const batch = x.shape.dims[0];
        const total_dim = x.shape.dims[1];
        if (total_dim != self.dim * 2) return error.ShapeMismatch;
        const sw = self.s_weights orelse return error.WeightsNotSet;
        const tw = self.t_weights orelse return error.WeightsNotSet;
        if (self.s_rows != self.dim or self.s_cols != self.dim) return error.ShapeMismatch;
        if (self.t_rows != self.dim or self.t_cols != self.dim) return error.ShapeMismatch;

        var out = try Tensor.init(alloc, &.{ batch, total_dim });
        errdefer out.deinit();

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            const row_base = b * total_dim;
            const x1 = x.data[row_base .. row_base + self.dim];
            const x2 = x.data[row_base + self.dim .. row_base + total_dim];

            var s_out = try alloc.alloc(f32, self.dim);
            defer alloc.free(s_out);
            var t_out = try alloc.alloc(f32, self.dim);
            defer alloc.free(t_out);

            var d: usize = 0;
            while (d < self.dim) : (d += 1) {
                var acc_s: f32 = 0.0;
                var acc_t: f32 = 0.0;
                var k: usize = 0;
                while (k < self.dim) : (k += 1) {
                    acc_s += @as(f32, sw[d * self.s_cols + k]) * x2[k];
                    acc_t += @as(f32, tw[d * self.t_cols + k]) * x1[k];
                }
                s_out[d] = @exp(std.math.clamp(acc_s, -5.0, 5.0));
                t_out[d] = acc_t;
            }

            const out_base = b * total_dim;
            d = 0;
            while (d < self.dim) : (d += 1) {
                out.data[out_base + d] = x1[d] * s_out[d];
            }
            d = 0;
            while (d < self.dim) : (d += 1) {
                out.data[out_base + self.dim + d] = x2[d] + t_out[d];
            }
        }
        return out;
    }
};
