// src/optimizer/adam.zig
const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;
const Tensor = @import("../core/tensor.zig").Tensor;

pub const AdamConfig = struct {
    lr: f32 = 0.001,
    beta1: f32 = 0.9,
    beta2: f32 = 0.999,
    epsilon: f32 = 1e-8,
    weight_decay: f32 = 0.0,
};

pub const AdamState = struct {
    m: []Tensor,
    v: []Tensor,
    step: u64,
    allocator: Allocator,

    pub fn init(alloc: Allocator, params: []const Tensor) !AdamState {
        const m = try alloc.alloc(Tensor, params.len);
        errdefer alloc.free(m);
        const v = try alloc.alloc(Tensor, params.len);
        errdefer alloc.free(v);

        var initialized: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < initialized) : (j += 1) {
                m[j].deinit();
                v[j].deinit();
            }
        }

        for (params, 0..) |p, i| {
            m[i] = try Tensor.zeros(alloc, p.shape.dims);
            errdefer m[i].deinit();
            v[i] = try Tensor.zeros(alloc, p.shape.dims);
            initialized += 1;
        }

        return AdamState{
            .m = m,
            .v = v,
            .step = 0,
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *AdamState) void {
        for (self.m) |*mt| mt.deinit();
        for (self.v) |*vt| vt.deinit();
        self.allocator.free(self.m);
        self.allocator.free(self.v);
    }
};

pub fn step(params: []Tensor, grads: []const Tensor, state: *AdamState, cfg: AdamConfig) !void {
    if (params.len != grads.len or params.len != state.m.len) return error.LengthMismatch;

    state.step += 1;
    const t_f = @as(f32, @floatFromInt(state.step));
    const bias_corr1 = 1.0 - math.pow(f32, cfg.beta1, t_f);
    const bias_corr2 = 1.0 - math.pow(f32, cfg.beta2, t_f);

    for (params, grads, state.m, state.v) |*param, grad, *mt, *vt| {
        if (param.data.len != grad.data.len) return error.ShapeMismatch;
        if (param.data.len != mt.data.len) return error.ShapeMismatch;

        for (param.data, grad.data, mt.data, vt.data) |*p, g, *m_val, *v_val| {
            var g_effective = g;
            if (cfg.weight_decay != 0.0) {
                g_effective += cfg.weight_decay * p.*;
            }
            m_val.* = cfg.beta1 * m_val.* + (1.0 - cfg.beta1) * g_effective;
            v_val.* = cfg.beta2 * v_val.* + (1.0 - cfg.beta2) * g_effective * g_effective;
            const m_hat = m_val.* / bias_corr1;
            const v_hat = v_val.* / bias_corr2;
            p.* -= cfg.lr * m_hat / (@sqrt(v_hat) + cfg.epsilon);
        }
    }
