const CRC32_TABLE: [256]u32 = blk: {
    var table: [256]u32 = undefined;
    var i: u32 = 0;
    while (i < 256) : (i += 1) {
        var crc: u32 = i;
        var j: u32 = 0;
        while (j < 8) : (j += 1) {
            if (crc & 1 != 0) {
                crc = 0xEDB88320 ^ (crc >> 1);
            } else {
                crc >>= 1;
            }
        }
        table[i] = crc;
    }
    break :blk table;
};

fn crc32Update(crc: u32, data: []const u8) u32 {
    var c = crc ^ 0xFFFFFFFF;
    for (data) |b| {
        c = CRC32_TABLE[(c ^ b) & 0xFF] ^ (c >> 8);
    }
    return c ^ 0xFFFFFFFF;
}

fn crc32UpdateSlice(crc: u32, data: []const u8) u32 {
    return crc32Update(crc, data);
}

fn crcUpdateU32LE(crc: u32, value: u32) u32 {
    var buf: [4]u8 = undefined;
    std.mem.writeInt(u32, &buf, value, .little);
