    defer layer_registry_mutex.unlock();
    try ensureLayerRegistry(allocator);
    const id = layer_registry_next_id;
    layer_registry_next_id +%= 1;
    if (layer_registry_next_id == 0) layer_registry_next_id = 1;
    try layer_registry.?.put(id, .{ .core = core, .active_ops = 0, .destroyed = false });
