fn releaseLayerCore(id: u64) void {
    layer_registry_mutex.lock();
    defer layer_registry_mutex.unlock();
    if (layer_registry) |*reg| {
        if (reg.getPtr(id)) |entry| {
            if (entry.active_ops > 0) entry.active_ops -= 1;
            if (entry.destroyed and entry.active_ops == 0) {
                entry.core.deinitOwned();
                layer_registry_allocator.?.destroy(entry.core);
                _ = reg.remove(id);
            }
        }
    }
}

fn requestDestroyLayerCore(id: u64) void {
    layer_registry_mutex.lock();
    defer layer_registry_mutex.unlock();
    if (layer_registry) |*reg| {
        if (reg.getPtr(id)) |entry| {
            entry.destroyed = true;
            if (entry.active_ops == 0) {
                entry.core.deinitOwned();
                layer_registry_allocator.?.destroy(entry.core);
                _ = reg.remove(id);
            }
        }
    }
}

fn bindLayerHandle(id: u64, handle_addr: usize) !void {
    layer_registry_mutex.lock();
    defer layer_registry_mutex.unlock();
    if (layer_handle_owner_map) |*m| {
        if (m.get(id)) |existing_addr| {
            if (existing_addr != handle_addr) return error.HandleCopied;
        } else {
            try m.put(id, handle_addr);
        }
    }
}

fn shouldDestroyLayerHandle(id: u64, handle_addr: usize) bool {
    layer_registry_mutex.lock();
    defer layer_registry_mutex.unlock();
    if (layer_handle_owner_map) |*m| {
        if (m.get(id)) |existing_addr| {
            if (existing_addr == handle_addr) {
                _ = m.remove(id);
                return true;
            }
        }
    }
    return false;
}

pub const RSFLayer = struct {
    id: u64 = 0,

    pub fn init(allocator: Allocator, dim: usize) !RSFLayer {
        return initWithConfig(allocator, dim, .{});
    }

    pub fn initWithConfig(allocator: Allocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        const core = try allocator.create(LayerCore);
        errdefer allocator.destroy(core);
        core.* = try LayerCore.initOwned(allocator, dim, config);
        errdefer core.deinitOwned();
        const id = try registerLayerCore(allocator, core);
        var handle = RSFLayer{ .id = id };
        try bindLayerHandle(id, @intFromPtr(&handle));
        return handle;
    }

    pub fn initWithArena(arena: *memory.ArenaAllocator, dim: usize) !RSFLayer {
        return initWithConfig(arena.allocator(), dim, .{});
    }

    pub fn initWithPool(pool: *memory.PoolAllocator, dim: usize) !RSFLayer {
        return initWithConfig(pool.allocator(), dim, .{});
    }

    pub fn initWithSlab(slab: *memory.SlabAllocator, dim: usize) !RSFLayer {
        return initWithConfig(slab.allocator(), dim, .{});
    }

    pub fn initWithBuddy(buddy: *memory.BuddyAllocator, dim: usize) !RSFLayer {
        return initWithConfig(buddy.allocator(), dim, .{});
    }

    pub fn deinit(self: *RSFLayer) void {
        if (self.id == 0) return;
        if (shouldDestroyLayerHandle(self.id, @intFromPtr(self))) {
            requestDestroyLayerCore(self.id);
        }
        self.id = 0;
    }

    pub fn ensureGradients(self: *RSFLayer) !void {
        const core = try acquireLayerCore(self.id);
        defer releaseLayerCore(self.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();
        try core.ensureGradients();
    }

    pub fn zeroGradients(self: *RSFLayer) !void {
        const core = try acquireLayerCore(self.id);
        defer releaseLayerCore(self.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();
        core.zeroGradients();
    }

    pub fn forward(self: *RSFLayer, x: *Tensor) !void {
        const core = try acquireLayerCore(self.id);
        defer releaseLayerCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        try core.forwardChecked(x);
    }

    pub fn inverse(self: *RSFLayer, y: *Tensor) !void {
        const core = try acquireLayerCore(self.id);
        defer releaseLayerCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        try core.inverseChecked(y);
    }

    pub fn verifyInvertible(self: *RSFLayer, x1_in: []const f32, x2_in: []const f32, abs_tol: f32, rel_tol: f32) !bool {
        try validateComparisonTolerances(abs_tol, rel_tol);
        const core = try acquireLayerCore(self.id);
        defer releaseLayerCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        const d = core.dim;
        if (x1_in.len != d or x2_in.len != d) return error.ShapeMismatch;

        const sa = scratchAllocator();
        const y1 = try sa.alloc(f32, d);
        defer sa.free(y1);
        const y2 = try sa.alloc(f32, d);
        defer sa.free(y2);
        @memcpy(y1, x1_in);
        @memcpy(y2, x2_in);

        try core.forwardInPlace(y1, y2);
        try core.inverseInPlace(y1, y2);

        for (x1_in, y1) |orig, recovered| {
            const diff = @abs(orig - recovered);
            const scale = rel_tol * @max(@abs(orig), @abs(recovered));
            if (diff > abs_tol + scale) return false;
        }
        for (x2_in, y2) |orig, recovered| {
            const diff = @abs(orig - recovered);
            const scale = rel_tol * @max(@abs(orig), @abs(recovered));
            if (diff > abs_tol + scale) return false;
        }
        return true;
    }
};

const RSFCore = struct {
    allocator: Allocator,
    dim: usize,
    num_layers: usize,
    layers: []LayerCore,
    cfg: RSFConfig,
    rwlock: std.Thread.RwLock,
    gpu_accel: ?accel.RSFAccelerator,
    gpu_available: std.atomic.Value(u8),
    gpu_weight_version: u64,
    cpu_weight_version: u64,
    f16_buf: ?[]f16,
};

fn splitInto(core: *const RSFCore, x: *const Tensor, x1: *Tensor, x2: *Tensor) !void {
    const batch = x.shape.dims[0];
    const d = core.dim;
    if (x.shape.dims[1] != d * 2) return error.ShapeMismatch;
    if (!tensorHasShape(x1, batch, d)) return error.ShapeMismatch;
    if (!tensorHasShape(x2, batch, d)) return error.ShapeMismatch;
    var b: usize = 0;
    while (b < batch) : (b += 1) {
        @memcpy(x1.data[b * d .. (b + 1) * d], x.data[b * d * 2 .. b * d * 2 + d]);
        @memcpy(x2.data[b * d .. (b + 1) * d], x.data[b * d * 2 + d .. b * d * 2 + d * 2]);
    }
}

fn mergeFrom(core: *const RSFCore, x1: *const Tensor, x2: *const Tensor, out: *Tensor) !void {
    const batch = x1.shape.dims[0];
    const d = core.dim;
    if (!tensorHasShape(x2, batch, d)) return error.ShapeMismatch;
    if (!tensorHasShape(out, batch, d * 2)) return error.ShapeMismatch;
    var b: usize = 0;
    while (b < batch) : (b += 1) {
        @memcpy(out.data[b * d * 2 .. b * d * 2 + d], x1.data[b * d .. (b + 1) * d]);
        @memcpy(out.data[b * d * 2 + d .. b * d * 2 + d * 2], x2.data[b * d .. (b + 1) * d]);
    }
}

fn forwardOnCore(core: *RSFCore, x: *Tensor) !void {
    try validateTensor2D(x);
    const batch = x.shape.dims[0];
    const d = core.dim;
    if (x.shape.dims[1] != d * 2) return error.ShapeMismatch;
    var l: usize = 0;
    while (l < core.num_layers) : (l += 1) {
        const layer = &core.layers[l];
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            const row = x.data[b * d * 2 .. (b + 1) * d * 2];
            try layer.forwardInPlace(row[0..d], row[d .. d * 2]);
        }
    }
}

fn inverseOnCore(core: *RSFCore, y: *Tensor) !void {
    try validateTensor2D(y);
    const batch = y.shape.dims[0];
    const d = core.dim;
    if (y.shape.dims[1] != d * 2) return error.ShapeMismatch;
    var l: usize = core.num_layers;
    while (l > 0) {
        l -= 1;
        const layer = &core.layers[l];
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            const row = y.data[b * d * 2 .. (b + 1) * d * 2];
            try layer.inverseInPlace(row[0..d], row[d .. d * 2]);
        }
    }
}

fn backwardOnCore(core: *RSFCore, grad_output: *const Tensor, input: *const Tensor, grad_input_out: *Tensor) !void {
    try validateTensor2D(grad_output);
    try validateTensor2D(input);
    try validateTensor2D(grad_input_out);
    const batch = input.shape.dims[0];
    const d = core.dim;
    if (input.shape.dims[1] != d * 2) return error.ShapeMismatch;
    if (!tensorHasShape(grad_output, batch, d * 2)) return error.ShapeMismatch;
    if (!tensorHasShape(grad_input_out, batch, d * 2)) return error.ShapeMismatch;

    const sa = scratchAllocator();

    var activations = try sa.alloc(Tensor, core.num_layers + 1);
    defer sa.free(activations);

    activations[0] = try tensorClone(sa, input);
    errdefer {
        var k: usize = 0;
        while (k <= core.num_layers) : (k += 1) {
            if (k > 0 or true) activations[k].deinit();
        }
    }

    var l: usize = 0;
    while (l < core.num_layers) : (l += 1) {
        activations[l + 1] = try tensorClone(sa, &activations[l]);
        const layer = &core.layers[l];
        const b_inner = activations[l + 1].shape.dims[0];
        var b: usize = 0;
        while (b < b_inner) : (b += 1) {
            const row = activations[l + 1].data[b * d * 2 .. (b + 1) * d * 2];
            try layer.forwardInPlace(row[0..d], row[d .. d * 2]);
        }
    }

    var grad_buf = try tensorClone(sa, grad_output);
    defer grad_buf.deinit();

    const tmp_x1 = try sa.alloc(f32, d);
    defer sa.free(tmp_x1);
    const tmp_x2 = try sa.alloc(f32, d);
    defer sa.free(tmp_x2);
    const tmp_dx1 = try sa.alloc(f32, d);
    defer sa.free(tmp_dx1);
    const tmp_dx2 = try sa.alloc(f32, d);
    defer sa.free(tmp_dx2);
    const tmp_dy1 = try sa.alloc(f32, d);
    defer sa.free(tmp_dy1);
    const tmp_ds = try sa.alloc(f32, d);
    defer sa.free(tmp_ds);

    var layer_idx: usize = core.num_layers;
    while (layer_idx > 0) {
        layer_idx -= 1;
        const layer = &core.layers[layer_idx];
        try layer.ensureGradients();
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            const y_row = activations[layer_idx + 1].data[b * d * 2 .. (b + 1) * d * 2];
            const dy_row = grad_buf.data[b * d * 2 .. (b + 1) * d * 2];
            @memset(tmp_ds, 0);
            try layer.backwardFromOutputs(
                y_row[0..d],
                y_row[d .. d * 2],
                dy_row[0..d],
                dy_row[d .. d * 2],
                tmp_x1,
                tmp_x2,
                tmp_dx1,
                tmp_dx2,
                tmp_dy1,
                tmp_ds,
                batch,
            );
            @memcpy(grad_buf.data[b * d * 2 .. b * d * 2 + d], tmp_dy1);
            @memcpy(grad_buf.data[b * d * 2 + d .. b * d * 2 + d * 2], tmp_dx2);
        }
    }

    @memcpy(grad_input_out.data, grad_buf.data);

    l = 0;
    while (l <= core.num_layers) : (l += 1) {
        activations[l].deinit();
    }
}

fn modelGPUCompatible(core: *const RSFCore) bool {
    if (!accel.gpu_enabled) return false;
    if (core.num_layers != 1) return false;
    if (core.cfg.clip_min != -5.0 or core.cfg.clip_max != 5.0) return false;
    const layer = &core.layers[0];
    for (layer.s_bias.data) |v| if (v != 0.0) return false;
    for (layer.t_bias.data) |v| if (v != 0.0) return false;
    return true;
}

fn syncAllLayersGPU(core: *RSFCore) !void {
    if (!accel.gpu_enabled) return error.GPUUnsupportedConfiguration;
    var ga = core.gpu_accel orelse return error.GPUNotInitialized;
    const d = core.dim;
    const layer = &core.layers[0];

    const sa = scratchAllocator();
    const f16_s = try sa.alloc(f16, d * d);
    defer sa.free(f16_s);
    const f16_t = try sa.alloc(f16, d * d);
    defer sa.free(f16_t);

    for (layer.s_weight.data, 0..) |v, i| f16_s[i] = @floatCast(v);
    for (layer.t_weight.data, 0..) |v, i| f16_t[i] = @floatCast(v);

    try ga.setWeightsS(f16_s, d, d);
    try ga.setWeightsT(f16_t, d, d);
    core.gpu_weight_version = core.cpu_weight_version;
}

fn tryForwardGPU(core: *RSFCore, x: *Tensor) !bool {
    if (core.gpu_accel == null) return false;
    if (!modelGPUCompatible(core)) return false;
    if (core.gpu_weight_version != core.cpu_weight_version) {
        syncAllLayersGPU(core) catch {
            disableGPU(core);
            return false;
        };
    }
    var ga = &(core.gpu_accel orelse return false);
    const result = ga.forwardFromTensor(x, core.allocator) catch {
        disableGPU(core);
        return false;
    };
    @memcpy(x.data, result.data);
    var r = result;
    r.deinit();
    return true;
}

fn disableGPU(core: *RSFCore) void {
    if (core.gpu_accel) |*ga| ga.deinit();
    core.gpu_accel = null;
    if (core.f16_buf) |buf| core.allocator.free(buf);
    core.f16_buf = null;
    core.gpu_available.store(0, .release);
}

const RSFRegistryEntry = struct {
    core: *RSFCore,
    active_ops: usize,
    destroyed: bool,
};

var rsf_registry_mutex: std.Thread.Mutex = .{};
var rsf_registry: ?std.AutoHashMap(u64, RSFRegistryEntry) = null;
var rsf_registry_next_id: u64 = 1;
var rsf_handle_owner_map: ?std.AutoHashMap(u64, usize) = null;
var rsf_registry_allocator: ?Allocator = null;

fn ensureRSFRegistry(allocator: Allocator) !void {
    if (rsf_registry == null) {
        rsf_registry = std.AutoHashMap(u64, RSFRegistryEntry).init(allocator);
        rsf_handle_owner_map = std.AutoHashMap(u64, usize).init(allocator);
        rsf_registry_allocator = allocator;
    }
}

fn registerRSFCore(allocator: Allocator, core: *RSFCore) !u64 {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    try ensureRSFRegistry(allocator);
    const id = rsf_registry_next_id;
    rsf_registry_next_id +%= 1;
    if (rsf_registry_next_id == 0) rsf_registry_next_id = 1;
    try rsf_registry.?.put(id, .{ .core = core, .active_ops = 0, .destroyed = false });
    return id;
}

fn acquireRSFCore(id: u64) !*RSFCore {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    const reg = rsf_registry orelse return error.RegistryNotInitialized;
    var entry = reg.getPtr(id) orelse return error.InvalidHandle;
    if (entry.destroyed) return error.HandleDestroyed;
    entry.active_ops += 1;
    return entry.core;
}

fn releaseRSFCore(id: u64) void {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    if (rsf_registry) |*reg| {
        if (reg.getPtr(id)) |entry| {
            if (entry.active_ops > 0) entry.active_ops -= 1;
            if (entry.destroyed and entry.active_ops == 0) {
                freeRSFCoreMemory(entry.core);
                _ = reg.remove(id);
            }
        }
    }
}

fn freeRSFCoreMemory(core: *RSFCore) void {
    for (core.layers) |*layer| layer.deinitOwned();
    core.allocator.free(core.layers);
    if (core.gpu_accel) |*ga| ga.deinit();
    if (core.f16_buf) |buf| core.allocator.free(buf);
    rsf_registry_allocator.?.destroy(core);
}

fn requestDestroyRSFCore(id: u64) void {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    if (rsf_registry) |*reg| {
        if (reg.getPtr(id)) |entry| {
            entry.destroyed = true;
            if (entry.active_ops == 0) {
                freeRSFCoreMemory(entry.core);
                _ = reg.remove(id);
            }
        }
    }
}

fn bindRSFHandle(id: u64, handle_addr: usize) !void {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    if (rsf_handle_owner_map) |*m| {
        if (m.get(id)) |existing_addr| {
            if (existing_addr != handle_addr) return error.HandleCopied;
        } else {
            try m.put(id, handle_addr);
        }
    }
}

fn shouldDestroyRSFHandle(id: u64, handle_addr: usize) bool {
    rsf_registry_mutex.lock();
    defer rsf_registry_mutex.unlock();
    if (rsf_handle_owner_map) |*m| {
        if (m.get(id)) |existing_addr| {
            if (existing_addr == handle_addr) {
                _ = m.remove(id);
                return true;
            }
        }
    }
    return false;
}

fn validateModelMetadata(core: *const RSFCore) !void {
    const d = core.dim;
    for (core.layers) |*layer| {
        if (layer.dim != d) return error.MetadataMismatch;
        if (!tensorHasShape(&layer.s_weight, d, d)) return error.MetadataMismatch;
        if (!tensorHasShape(&layer.t_weight, d, d)) return error.MetadataMismatch;
        if (!tensorHasShape(&layer.s_bias, 1, d)) return error.MetadataMismatch;
        if (!tensorHasShape(&layer.t_bias, 1, d)) return error.MetadataMismatch;
    }
}

const SavedLayerSnapshot = struct {
    s_weight: Tensor,
    t_weight: Tensor,
    s_bias: Tensor,
    t_bias: Tensor,
    clip_min: f32,
    clip_max: f32,
    grad_mean: bool,
};

const SavedModelSnapshot = struct {
    layers: []SavedLayerSnapshot,
    dim: u64,
    num_layers: u64,
    cfg: RSFConfig,
    allocator: Allocator,

    fn deinit(self: *SavedModelSnapshot) void {
        for (self.layers) |*layer| {
            layer.s_weight.deinit();
            layer.t_weight.deinit();
            layer.s_bias.deinit();
            layer.t_bias.deinit();
        }
        self.allocator.free(self.layers);
    }
};

fn snapshotModelForSave(allocator: Allocator, core: *const RSFCore) !SavedModelSnapshot {
    const layers = try allocator.alloc(SavedLayerSnapshot, core.num_layers);
    errdefer allocator.free(layers);

    var initialized: usize = 0;
    errdefer {
        var k: usize = 0;
        while (k < initialized) : (k += 1) {
            layers[k].s_weight.deinit();
            layers[k].t_weight.deinit();
            layers[k].s_bias.deinit();
            layers[k].t_bias.deinit();
        }
    }

    for (core.layers, 0..) |*layer, i| {
        layers[i].s_weight = try tensorClone(allocator, &layer.s_weight);
        errdefer layers[i].s_weight.deinit();
        layers[i].t_weight = try tensorClone(allocator, &layer.t_weight);
        errdefer layers[i].t_weight.deinit();
        layers[i].s_bias = try tensorClone(allocator, &layer.s_bias);
        errdefer layers[i].s_bias.deinit();
        layers[i].t_bias = try tensorClone(allocator, &layer.t_bias);
        errdefer layers[i].t_bias.deinit();
        layers[i].clip_min = layer.clip_min;
        layers[i].clip_max = layer.clip_max;
        layers[i].grad_mean = layer.grad_mean;
        initialized += 1;
    }

    return SavedModelSnapshot{
        .layers = layers,
        .dim = @intCast(core.dim),
        .num_layers = @intCast(core.num_layers),
        .cfg = core.cfg,
        .allocator = allocator,
    };
}

fn writeTensorDataVersion4(writer: anytype, crc_in: u32, t: *const Tensor) !u32 {
    var crc = crc_in;
    const ndim: u64 = @intCast(t.shape.dims.len);
    var buf8: [8]u8 = undefined;
    std.mem.writeInt(u64, &buf8, ndim, .little);
    try writer.writeAll(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);
    for (t.shape.dims) |dim| {
        const d: u64 = @intCast(dim);
        std.mem.writeInt(u64, &buf8, d, .little);
        try writer.writeAll(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
    }
    var buf4: [4]u8 = undefined;
    for (t.data) |v| {
        const bits: u32 = @bitCast(v);
        std.mem.writeInt(u32, &buf4, bits, .little);
        try writer.writeAll(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);
    }
    return crc;
}

fn writeSnapshotVersion4ToPath(path: []const u8, snapshot: *const SavedModelSnapshot) !void {
    const dir = std.fs.cwd();
    const base_name = std.fs.path.basename(path);
    var parent_dir = dir;
    const parent_path = std.fs.path.dirname(path);
    var opened_parent = false;
    if (parent_path) |pp| {
        if (pp.len > 0) {
            parent_dir = try dir.openDir(pp, .{});
            opened_parent = true;
        }
    }
    defer if (opened_parent) parent_dir.close();

    const tmp_file = try createUniqueTempFile(parent_dir, base_name);
    var file_closed = false;
    var tmp_name_buf: [512]u8 = undefined;
    _ = tmp_name_buf;

    var buf_writer = std.io.bufferedWriter(tmp_file.writer());
    const writer = buf_writer.writer();

    var crc: u32 = 0;
    const magic = "RSF0";
    try writer.writeAll(magic);
    crc = crc32UpdateSlice(crc, magic);

    var buf4: [4]u8 = undefined;
    var buf8: [8]u8 = undefined;

    std.mem.writeInt(u32, &buf4, 4, .little);
    try writer.writeAll(&buf4);
    crc = crc32UpdateSlice(crc, &buf4);

    std.mem.writeInt(u64, &buf8, snapshot.num_layers, .little);
    try writer.writeAll(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);

    std.mem.writeInt(u64, &buf8, snapshot.dim, .little);
    try writer.writeAll(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);

    std.mem.writeInt(u32, &buf4, @bitCast(snapshot.cfg.clip_min), .little);
    try writer.writeAll(&buf4);
    crc = crc32UpdateSlice(crc, &buf4);

    std.mem.writeInt(u32, &buf4, @bitCast(snapshot.cfg.clip_max), .little);
    try writer.writeAll(&buf4);
    crc = crc32UpdateSlice(crc, &buf4);

    const gm_byte: u8 = if (snapshot.cfg.grad_mean) 1 else 0;
    try writer.writeByte(gm_byte);
    crc = crcUpdateU8(crc, gm_byte);

    std.mem.writeInt(u64, &buf8, @intCast(snapshot.cfg.max_dim), .little);
    try writer.writeAll(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);

    std.mem.writeInt(u64, &buf8, @intCast(snapshot.cfg.max_layers), .little);
    try writer.writeAll(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);

    for (snapshot.layers) |*layer| {
        std.mem.writeInt(u32, &buf4, @bitCast(layer.clip_min), .little);
        try writer.writeAll(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);

        std.mem.writeInt(u32, &buf4, @bitCast(layer.clip_max), .little);
        try writer.writeAll(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);

        const lgm_byte: u8 = if (layer.grad_mean) 1 else 0;
        try writer.writeByte(lgm_byte);
        crc = crcUpdateU8(crc, lgm_byte);

        crc = try writeTensorDataVersion4(writer, crc, &layer.s_weight);
        crc = try writeTensorDataVersion4(writer, crc, &layer.t_weight);
        crc = try writeTensorDataVersion4(writer, crc, &layer.s_bias);
        crc = try writeTensorDataVersion4(writer, crc, &layer.t_bias);
    }

    std.mem.writeInt(u32, &buf4, crc, .little);
    try writer.writeAll(&buf4);
    try buf_writer.flush();
    try tmp_file.sync();
    tmp_file.close();
    file_closed = true;

    try parent_dir.rename(base_name, base_name);
    _ = file_closed;
}

fn readTensorData(reader: anytype, allocator: Allocator, crc_in: u32) !struct { t: Tensor, crc: u32 } {
    var crc = crc_in;
    var buf8: [8]u8 = undefined;
    var buf4: [4]u8 = undefined;

    try reader.readNoEof(&buf8);
    crc = crc32UpdateSlice(crc, &buf8);
    const ndim = std.mem.readInt(u64, &buf8, .little);
    if (ndim == 0 or ndim > 8) return error.InvalidTensorDims;

    var dims: [8]usize = undefined;
    var total: usize = 1;
    var i: usize = 0;
    while (i < ndim) : (i += 1) {
        try reader.readNoEof(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
        const d = std.mem.readInt(u64, &buf8, .little);
        dims[i] = try checkedCastU64ToUsize(d);
        if (dims[i] == 0) return error.InvalidDim;
        total = try checkedMul(total, dims[i]);
    }

    var t = try Tensor.init(allocator, dims[0..ndim]);
    errdefer t.deinit();

    for (t.data) |*v| {
        try reader.readNoEof(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);
        v.* = @bitCast(std.mem.readInt(u32, &buf4, .little));
    }
    _ = total;
    return .{ .t = t, .crc = crc };
}

fn readEncodedBool(reader: anytype, crc_in: u32) !struct { val: bool, crc: u32 } {
    const b = try reader.readByte();
    const crc = crcUpdateU8(crc_in, b);
    return .{ .val = b != 0, .crc = crc };
}

pub const RSF = struct {
    id: u64 = 0,

    pub fn init(allocator: Allocator, dim: usize, num_layers: usize) !RSF {
        return initWithConfig(allocator, dim, num_layers, .{});
    }

    pub fn initWithConfig(allocator: Allocator, dim: usize, num_layers: usize, cfg: RSFConfig) !RSF {
        try validateModelConfigValues(dim, num_layers, cfg);

        const core = try allocator.create(RSFCore);
        errdefer allocator.destroy(core);

        const layers = try allocator.alloc(LayerCore, num_layers);
        errdefer allocator.free(layers);

        var initialized: usize = 0;
        errdefer {
            var k: usize = 0;
            while (k < initialized) : (k += 1) {
                layers[k].deinitOwned();
            }
        }

        var l: usize = 0;
        while (l < num_layers) : (l += 1) {
            const layer_cfg = RSFLayerConfig{
                .clip_min = cfg.clip_min,
                .clip_max = cfg.clip_max,
                .seed_offset = @as(u64, @intCast(l)) * 10007,
                .grad_mean = cfg.grad_mean,
            };
            layers[l] = try LayerCore.initOwned(allocator, dim, layer_cfg);
            initialized += 1;
        }

        var gpu_accel: ?accel.RSFAccelerator = null;
        if (accel.gpu_enabled) {
            gpu_accel = accel.RSFAccelerator.init(dim, allocator) catch null;
        }

        core.* = RSFCore{
            .allocator = allocator,
            .dim = dim,
            .num_layers = num_layers,
            .layers = layers,
            .cfg = cfg,
            .rwlock = .{},
            .gpu_accel = gpu_accel,
            .gpu_available = std.atomic.Value(u8).init(if (gpu_accel != null) 1 else 0),
            .gpu_weight_version = 0,
            .cpu_weight_version = 1,
            .f16_buf = null,
        };

        try validateModelMetadata(core);

        const id = try registerRSFCore(allocator, core);
        var handle = RSF{ .id = id };
        try bindRSFHandle(id, @intFromPtr(&handle));
        return handle;
    }

    pub fn deinit(self: *RSF) void {
        if (self.id == 0) return;
        if (shouldDestroyRSFHandle(self.id, @intFromPtr(self))) {
            requestDestroyRSFCore(self.id);
        }
        self.id = 0;
    }

    pub fn isGPUAvailable(self: *const RSF) bool {
        const core = acquireRSFCore(self.id) catch return false;
        defer releaseRSFCore(self.id);
        return core.gpu_available.load(.acquire) != 0;
    }

    pub fn syncWeightsToGPU(self: *RSF) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        try syncAllLayersGPU(core);
    }

    pub fn zeroGradients(self: *RSF) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();
        for (core.layers) |*layer| layer.zeroGradients();
    }

    pub fn forwardCPU(self: *RSF, x: *Tensor) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        try forwardOnCore(core, x);
    }

    pub fn forward(self: *RSF, x: *Tensor) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();
        if (core.gpu_available.load(.acquire) != 0) {
            if (core.gpu_weight_version != core.cpu_weight_version) {
                syncAllLayersGPU(core) catch {};
            }
            const used_gpu = tryForwardGPU(core, x) catch false;
            if (used_gpu) return;
        }
        try forwardOnCore(core, x);
    }

    pub fn inverse(self: *RSF, y: *Tensor) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();
        try inverseOnCore(core, y);
    }

    pub fn backward(self: *RSF, grad_output: *const Tensor, input: *const Tensor, grad_input_out: *Tensor) !void {
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();
        try backwardOnCore(core, grad_output, input, grad_input_out);
    }

    pub fn verifyInvertible(self: *RSF, x: *Tensor, abs_tol: f32, rel_tol: f32) !bool {
        try validateComparisonTolerances(abs_tol, rel_tol);
        const core = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core.rwlock.lockShared();
        defer core.rwlock.unlockShared();

        const sa = scratchAllocator();
        var cloned = try tensorClone(sa, x);
        defer cloned.deinit();

        try forwardOnCore(core, &cloned);
        try inverseOnCore(core, &cloned);

        return tensorAllCloseEq(x, &cloned, abs_tol, rel_tol);
    }

    pub fn save(self: *RSF, path: []const u8) !void {
        const core = try acquireRSFCore(self.id);
        var snapshot: SavedModelSnapshot = blk: {
            core.rwlock.lockShared();
            defer core.rwlock.unlockShared();
            break :blk try snapshotModelForSave(core.allocator, core);
        };
        releaseRSFCore(self.id);
        defer snapshot.deinit();
        try writeSnapshotVersion4ToPath(path, &snapshot);
    }

    pub fn load(allocator: Allocator, path: []const u8) !RSF {
        return loadWithConfig(allocator, path, null);
    }

    pub fn loadWithConfig(allocator: Allocator, path: []const u8, policy: ?RSFConfig) !RSF {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        var buf_reader = std.io.bufferedReader(file.reader());
        const reader = buf_reader.reader();

        var magic: [4]u8 = undefined;
        try reader.readNoEof(&magic);
        if (!std.mem.eql(u8, &magic, "RSF0")) return error.InvalidMagic;
        var crc: u32 = crc32UpdateSlice(0, &magic);

        var buf4: [4]u8 = undefined;
        var buf8: [8]u8 = undefined;

        try reader.readNoEof(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);
        const version = std.mem.readInt(u32, &buf4, .little);
        if (version != 4) return error.UnsupportedVersion;

        try reader.readNoEof(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
        const num_layers_u64 = std.mem.readInt(u64, &buf8, .little);

        try reader.readNoEof(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
        const dim_u64 = std.mem.readInt(u64, &buf8, .little);

        try reader.readNoEof(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);
        const clip_min: f32 = @bitCast(std.mem.readInt(u32, &buf4, .little));

        try reader.readNoEof(&buf4);
        crc = crc32UpdateSlice(crc, &buf4);
        const clip_max: f32 = @bitCast(std.mem.readInt(u32, &buf4, .little));

        const gm_result = try readEncodedBool(reader, crc);
        crc = gm_result.crc;
        const grad_mean = gm_result.val;

        try reader.readNoEof(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
        const max_dim_u64 = std.mem.readInt(u64, &buf8, .little);

        try reader.readNoEof(&buf8);
        crc = crc32UpdateSlice(crc, &buf8);
        const max_layers_u64 = std.mem.readInt(u64, &buf8, .little);

        const dim = try checkedCastU64ToUsize(dim_u64);
        const num_layers = try checkedCastU64ToUsize(num_layers_u64);
        const max_dim = try checkedCastU64ToUsize(max_dim_u64);
        const max_layers = try checkedCastU64ToUsize(max_layers_u64);

        var cfg = RSFConfig{
            .clip_min = clip_min,
            .clip_max = clip_max,
            .grad_mean = grad_mean,
            .max_dim = max_dim,
            .max_layers = max_layers,
        };

        if (policy) |p| {
            if (dim > p.max_dim) return error.DimExceedsMax;
            if (num_layers > p.max_layers) return error.LayersExceedMax;
            cfg.max_dim = p.max_dim;
            cfg.max_layers = p.max_layers;
        }

        try validateClipRange(clip_min, clip_max);
        if (dim == 0) return error.InvalidDim;
        if (num_layers == 0) return error.InvalidNumLayers;

        var rsf_model = try RSF.initWithConfig(allocator, dim, num_layers, cfg);
        errdefer rsf_model.deinit();

        const core = try acquireRSFCore(rsf_model.id);
        defer releaseRSFCore(rsf_model.id);
        core.rwlock.lock();
        defer core.rwlock.unlock();

        for (core.layers) |*layer| {
            try reader.readNoEof(&buf4);
            crc = crc32UpdateSlice(crc, &buf4);
            layer.clip_min = @bitCast(std.mem.readInt(u32, &buf4, .little));

            try reader.readNoEof(&buf4);
            crc = crc32UpdateSlice(crc, &buf4);
            layer.clip_max = @bitCast(std.mem.readInt(u32, &buf4, .little));

            const lgm_result = try readEncodedBool(reader, crc);
            crc = lgm_result.crc;
            layer.grad_mean = lgm_result.val;

            const sw_result = try readTensorData(reader, allocator, crc);
            crc = sw_result.crc;
            layer.s_weight.deinit();
            layer.s_weight = sw_result.t;

            const tw_result = try readTensorData(reader, allocator, crc);
            crc = tw_result.crc;
            layer.t_weight.deinit();
            layer.t_weight = tw_result.t;

            const sb_result = try readTensorData(reader, allocator, crc);
            crc = sb_result.crc;
            layer.s_bias.deinit();
            layer.s_bias = sb_result.t;

            const tb_result = try readTensorData(reader, allocator, crc);
            crc = tb_result.crc;
            layer.t_bias.deinit();
            layer.t_bias = tb_result.t;
        }

        try reader.readNoEof(&buf4);
        const file_crc = std.mem.readInt(u32, &buf4, .little);
        if (file_crc != crc) return error.CRCMismatch;

        var eof_check: [1]u8 = undefined;
        const n = try reader.read(&eof_check);
        if (n != 0) return error.TrailingData;

        return rsf_model;
    }

    pub fn saveLoadRoundtrip(allocator: Allocator, self: *RSF, path: []const u8, abs_tol: f32, rel_tol: f32) !bool {
        try validateComparisonTolerances(abs_tol, rel_tol);
        try self.save(path);
        var loaded = try RSF.load(allocator, path);
        defer loaded.deinit();

        const core_orig = try acquireRSFCore(self.id);
        defer releaseRSFCore(self.id);
        core_orig.rwlock.lockShared();
        defer core_orig.rwlock.unlockShared();

        const core_loaded = try acquireRSFCore(loaded.id);
        defer releaseRSFCore(loaded.id);
        core_loaded.rwlock.lockShared();
        defer core_loaded.rwlock.unlockShared();

        if (core_orig.dim != core_loaded.dim) return false;
        if (core_orig.num_layers != core_loaded.num_layers) return false;

        for (core_orig.layers, core_loaded.layers) |*lo, *ll| {
            if (!try tensorAllCloseEq(&lo.s_weight, &ll.s_weight, abs_tol, rel_tol)) return false;
            if (!try tensorAllCloseEq(&lo.t_weight, &ll.t_weight, abs_tol, rel_tol)) return false;
            if (!try tensorAllCloseEq(&lo.s_bias, &ll.s_bias, abs_tol, rel_tol)) return false;
            if (!try tensorAllCloseEq(&lo.t_bias, &ll.t_bias, abs_tol, rel_tol)) return false;
        }
        return true;
    }
};
