// src/main.zig
const std = @import("std");
const Tensor = @import("core/tensor.zig").Tensor;
const RSF = @import("processor/rsf.zig").RSF;
const adam = @import("optimizer/adam.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const dim: usize = 64;
    const num_layers: usize = 4;
    const batch_size: usize = 32;
    const num_samples: usize = 1000;
    const num_steps: usize = 100;
    const model_path = "model.rsf";

    var model = try RSF.init(allocator, dim, num_layers);
    defer model.deinit();

    var dataset = try Tensor.randomNormal(allocator, &.{ num_samples, dim * 2 }, 0.0, 1.0, 42);
    defer dataset.deinit();

    const core_ptr = try @import("processor/rsf.zig").acquireRSFCore(model.id);
    const all_params_count = num_layers * 4;
    var params_list = try allocator.alloc(Tensor, all_params_count);
    defer allocator.free(params_list);

    var pi: usize = 0;
    for (core_ptr.layers) |*layer| {
        params_list[pi] = layer.s_weight;
        params_list[pi + 1] = layer.t_weight;
        params_list[pi + 2] = layer.s_bias;
        params_list[pi + 3] = layer.t_bias;
        pi += 4;
    }
    @import("processor/rsf.zig").releaseRSFCore(model.id);

    var opt_state = try adam.AdamState.init(allocator, params_list);
    defer opt_state.deinit();

    const adam_cfg = adam.AdamConfig{
        .lr = 0.001,
        .beta1 = 0.9,
        .beta2 = 0.999,
        .epsilon = 1e-8,
        .weight_decay = 0.0,
    };

    var step_num: usize = 0;
    while (step_num < num_steps) : (step_num += 1) {
        try model.zeroGradients();

        const sample_start = (step_num * batch_size) % (num_samples - batch_size);
        var batch = try Tensor.init(allocator, &.{ batch_size, dim * 2 });
        defer batch.deinit();
        @memcpy(batch.data, dataset.data[sample_start * dim * 2 .. sample_start * dim * 2 + batch_size * dim * 2]);

        var forward_input = try @import("core/tensor.zig").Tensor.init(allocator, &.{ batch_size, dim * 2 });
        defer forward_input.deinit();
        @memcpy(forward_input.data, batch.data);

        try model.forward(&forward_input);

        var loss: f32 = 0.0;
        var grad_output = try Tensor.init(allocator, &.{ batch_size, dim * 2 });
        defer grad_output.deinit();

        const two_dim = dim * 2;
        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            var d: usize = 0;
            while (d < two_dim) : (d += 1) {
                const v = forward_input.data[b * two_dim + d];
                loss += 0.5 * v * v + 0.5 * std.math.log(f32, std.math.e, 2.0 * std.math.pi);
                grad_output.data[b * two_dim + d] = v / @as(f32, @floatFromInt(batch_size));
            }
        }
        loss /= @as(f32, @floatFromInt(batch_size));

        var grad_input = try Tensor.init(allocator, &.{ batch_size, dim * 2 });
        defer grad_input.deinit();

        try model.backward(&grad_output, &batch, &grad_input);

        var grads_list = try allocator.alloc(Tensor, all_params_count);
        defer allocator.free(grads_list);
        const core_bwd = try @import("processor/rsf.zig").acquireRSFCore(model.id);
        pi = 0;
        for (core_bwd.layers) |*layer| {
            grads_list[pi] = if (layer.s_weight_grad) |g| g else try Tensor.zeros(allocator, &.{ dim, dim });
            grads_list[pi + 1] = if (layer.t_weight_grad) |g| g else try Tensor.zeros(allocator, &.{ dim, dim });
            grads_list[pi + 2] = if (layer.s_bias_grad) |g| g else try Tensor.zeros(allocator, &.{ 1, dim });
            grads_list[pi + 3] = if (layer.t_bias_grad) |g| g else try Tensor.zeros(allocator, &.{ 1, dim });
            pi += 4;
        }
        @import("processor/rsf.zig").releaseRSFCore(model.id);

        try adam.step(params_list, grads_list, &opt_state, adam_cfg);

        const core_upd = try @import("processor/rsf.zig").acquireRSFCore(model.id);
        pi = 0;
        for (core_upd.layers) |*layer| {
            @memcpy(layer.s_weight.data, params_list[pi].data);
            @memcpy(layer.t_weight.data, params_list[pi + 1].data);
            @memcpy(layer.s_bias.data, params_list[pi + 2].data);
            @memcpy(layer.t_bias.data, params_list[pi + 3].data);
            pi += 4;
        }
        core_upd.cpu_weight_version += 1;
        @import("processor/rsf.zig").releaseRSFCore(model.id);

        try std.io.getStdOut().writer().print("step {d:4}: loss = {d:.6}\n", .{ step_num + 1, loss });
    }

    var verify_input = try Tensor.randomNormal(allocator, &.{ 8, dim * 2 }, 0.0, 1.0, 9999);
    defer verify_input.deinit();
    const invertible = try model.verifyInvertible(&verify_input, 1e-4, 1e-4);
    try std.io.getStdOut().writer().print("invertible: {}\n", .{invertible});

    const roundtrip_ok = try RSF.saveLoadRoundtrip(allocator, &model, model_path, 1e-6, 1e-6);
    try std.io.getStdOut().writer().print("roundtrip: {}\n", .{roundtrip_ok});
}
