// build.zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{ .preferred_optimize_mode = .ReleaseFast });

    const gpu_option = b.option(bool, "gpu", "Enable GPU acceleration") orelse false;

    const build_options = b.addOptions();
    build_options.addOption(bool, "gpu", gpu_option);

    const exe = b.addExecutable(.{
        .name = "kissofdeath",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });
    exe.root_module.addOptions("build_options", build_options);
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the application");
    run_step.dependOn(&run_cmd.step);

    const unit_tests = b.addTest(.{
        .root_source_file = b.path("src/core/tensor.zig"),
        .target = target,
        .optimize = optimize,
    });
    unit_tests.root_module.addOptions("build_options", build_options);

    const memory_tests = b.addTest(.{
        .root_source_file = b.path("src/core/memory.zig"),
        .target = target,
        .optimize = optimize,
    });
    memory_tests.root_module.addOptions("build_options", build_options);

    const rsf_tests = b.addTest(.{
        .root_source_file = b.path("src/processor/rsf.zig"),
        .target = target,
        .optimize = optimize,
    });
    rsf_tests.root_module.addOptions("build_options", build_options);

    const run_unit_tests = b.addRunArtifact(unit_tests);
    const run_memory_tests = b.addRunArtifact(memory_tests);
    const run_rsf_tests = b.addRunArtifact(rsf_tests);

    const test_step = b.step("test", "Run all unit tests");
    test_step.dependOn(&run_unit_tests.step);
    test_step.dependOn(&run_memory_tests.step);
    test_step.dependOn(&run_rsf_tests.step);
